/**
 * The two Mermaid icon packs the diagrams use, generated by scripts/build-diagram-icons.mjs (do not
 * edit the JSON by hand). Loaded on demand through src/lib/offline/lazy.ts (loadDiagramIcons), and
 * only once a diagram on the page names an icon, so pages without icons never fetch this chunk.
 *   tech:<name>  technology logos (svg-logos + Simple Icons, CC0-1.0)
 *   sd:<name>    generic roles / components (Tabler Icons, MIT), drawn in currentColor
 */
import type { IconPack } from "../mermaid-icons";
import techJson from "./tech.json";
import sdJson from "./sd.json";

export const tech = techJson as IconPack;
export const sd = sdJson as IconPack;
